import classes from './CatalogSection.module.css';
import Btn from '../../../Components/UI/Btn/Btn';
import { useState } from 'react';
import Modal from '../../../Components/Modal/Modal'
import Close from '../../../Components/UI/Close/Close'

const list = [
    {
      id: 1,
      name: 'Honda Vision',
      price: '2000 ₽ / сутки',
      img: 'https://avatars.mds.yandex.net/get-mpic/4080064/2a00000191c6bb5780d735ead75029a5efb2/orig',
    },
    {
      id: 2,
      name: 'Honda Wave 110',
      price: '1800 ₽ / сутки',
      img: 'https://avatars.mds.yandex.net/get-mpic/4080064/2a00000191c6bb5780d735ead75029a5efb2/orig',
    },
    {
      id: 3,
      name: 'Yamaha Nouvo',
      price: '2200 ₽ / сутки',
      img: 'https://avatars.mds.yandex.net/get-mpic/4080064/2a00000191c6bb5780d735ead75029a5efb2/orig',
    },
    {
      id: 4,
      name: 'Honda Air Blade',
      price: '2500 ₽ / сутки',
      img: 'https://avatars.mds.yandex.net/get-mpic/4080064/2a00000191c6bb5780d735ead75029a5efb2/orig',
    },
    {
      id: 5,
      name: 'Honda Winner X',
      price: '3500 ₽ / сутки',
      img: 'https://avatars.mds.yandex.net/get-mpic/4080064/2a00000191c6bb5780d735ead75029a5efb2/orig',
    },
    {
      id: 6,
      name: 'Quad ATV 250',
      price: '6000 ₽ / сутки',
      img: 'https://avatars.mds.yandex.net/get-mpic/4080064/2a00000191c6bb5780d735ead75029a5efb2/orig',
    },
  ]

const CatalogSection = ({ t }) => {
  const [isOpen, setIsOpen] = useState(false)
  return (
    <div className='section line-dark'>
      <div className="container">
        <div className='content'>
          <h2 className='h2'>Каталог</h2>

          <ul className={classes.list}>
            {list.map(item => (
              <li className={`${classes.item}`}>
                <img
                  className={classes.img}
                  src={item.img}
                  alt=""
                />
                <div className={classes.itemTexts}>
                  <p className='text-base'>{item.name}</p>
                  <p className='text-sm'>{item.price}</p>
                </div>
                <Btn isColor='dark' size='sm' onClick={() => setIsOpen(item)}>забронировать</Btn>
              </li>
            ))}
          </ul>
          {isOpen &&
            <Modal>
              <Close onClick={() => setIsOpen(false)}/>
              <div className={classes.modalContent}>
                <img className={classes.imgModal} src={isOpen.img} alt={`Фото full screen`} />

                <div className={classes.texts}>
                  <div className={classes.header}>
                    <h2 className='h2'>{isOpen.name}</h2>
                    <p className='text-sm'>{isOpen.price} р</p>
                  </div>
                  {isOpen.description != 'null' &&
                    <p className='text-sm'>{isOpen.description}</p>
                  }

                  <Btn isColor='dark' size='sm' onClick={() => setIsOpen(true)}>забронировать</Btn>
                </div>
              </div>
            </Modal>
          }
        </div>
      </div>
    </div>
  );
};

export default CatalogSection;
